export const defaults={consumption:350,tariff:8,exportRate:2.5,selfUse:75,yield:120,quote:60000,opex:1,load:5,subsidy:true,watt:500,length:2,width:1,setback:.6,spacing:.2};
export const money=n=>new Intl.NumberFormat('en-IN',{style:'currency',currency:'INR',maximumFractionDigits:0}).format(n);
export function subsidy(k){return 30000*Math.min(k,2)+18000*Math.min(Math.max(k-2,0),1);}
export function solar(count,a=defaults){const capacity=count*a.watt/1000,generation=capacity*a.yield,selfConsumed=Math.min(generation*a.selfUse/100,a.consumption),exported=Math.max(0,generation-selfConsumed),gross=capacity*a.quote,grant=a.subsidy?Math.min(gross,subsidy(capacity)):0,net=gross-grant,annual=(selfConsumed*a.tariff+exported*a.exportRate)*12-gross*a.opex/100;return {count,capacity,generation,selfConsumed,exported,gross,grant,net,annual,payback:annual>0&&capacity>0?net/annual:null,low:capacity*100,high:capacity*140};}
export const area=p=>Math.abs(p.reduce((s,a,i)=>{let b=p[(i+1)%p.length];return s+a.x*b.y-a.y*b.x;},0)/2);
const cross=(a,b,c)=>(b.x-a.x)*(c.y-a.y)-(b.y-a.y)*(c.x-a.x);
export function inside(p,poly){let yes=false;for(let i=0,j=poly.length-1;i<poly.length;j=i++){let a=poly[i],b=poly[j];if(Math.abs(cross(a,b,p))<1e-8&&p.x>=Math.min(a.x,b.x)&&p.x<=Math.max(a.x,b.x)&&p.y>=Math.min(a.y,b.y)&&p.y<=Math.max(a.y,b.y))return true;if((a.y>p.y)!==(b.y>p.y)&&p.x<(b.x-a.x)*(p.y-a.y)/(b.y-a.y)+a.x)yes=!yes;}return yes;}
const segCross=(a,b,c,d)=>cross(a,b,c)*cross(a,b,d)<-1e-8&&cross(c,d,a)*cross(c,d,b)<-1e-8;
export function simple(poly){if(poly.length<3||area(poly)<1)return false;for(let i=0;i<poly.length;i++)for(let j=i+1;j<poly.length;j++){if(j===i+1||(i===0&&j===poly.length-1))continue;if(segCross(poly[i],poly[(i+1)%poly.length],poly[j],poly[(j+1)%poly.length]))return false;}return true;}
const distance=(p,a,b)=>{const dx=b.x-a.x,dy=b.y-a.y,t=Math.max(0,Math.min(1,((p.x-a.x)*dx+(p.y-a.y)*dy)/(dx*dx+dy*dy||1)));return Math.hypot(p.x-a.x-t*dx,p.y-a.y-t*dy);};
export const corners=r=>[{x:r.x,y:r.y},{x:r.x+r.w,y:r.y},{x:r.x+r.w,y:r.y+r.h},{x:r.x,y:r.y+r.h}];
export function validPanel(r,roof,exclusions,others,a){const pts=corners(r);if(!pts.every(p=>inside(p,roof)))return false;for(let i=0;i<roof.length;i++){let u=roof[i],v=roof[(i+1)%roof.length];for(let j=0;j<4;j++){let c=pts[j],d=pts[(j+1)%4];if(segCross(u,v,c,d))return false;if(Math.min(distance(u,c,d),distance(v,c,d),distance(c,u,v),distance(d,u,v))+1e-8<a.setback)return false;}}const overlap=(o,g=0)=>r.x<o.x+o.w+g-1e-8&&r.x+r.w+g>o.x+1e-8&&r.y<o.y+o.h+g-1e-8&&r.y+r.h+g>o.y+1e-8;return !exclusions.some(o=>overlap(o))&&!others.some(o=>overlap(o,a.spacing));}
export function layout(roof,exclusions,a,limit=Infinity){const out=[];const minX=Math.min(...roof.map(p=>p.x)),minY=Math.min(...roof.map(p=>p.y)),maxX=Math.max(...roof.map(p=>p.x)),maxY=Math.max(...roof.map(p=>p.y));for(let y=minY+a.setback;y+a.length<=maxY;y+=a.length+a.spacing)for(let x=minX+a.setback;x+a.width<=maxX;x+=a.width+a.spacing){let r={id:out.length+1,x,y,w:a.width,h:a.length};if(validPanel(r,roof,exclusions,out,a)&&out.length<limit)out.push(r);}return out;}
export function usableArea(roof,exclusions,setback){let sum=0;for(let y=Math.min(...roof.map(p=>p.y))+.05;y<Math.max(...roof.map(p=>p.y));y+=.1)for(let x=Math.min(...roof.map(p=>p.x))+.05;x<Math.max(...roof.map(p=>p.x));x+=.1){const p={x,y};if(inside(p,roof)&&roof.every((v,i)=>distance(p,v,roof[(i+1)%roof.length])>=setback)&&!exclusions.some(r=>x>=r.x&&x<=r.x+r.w&&y>=r.y&&y<=r.y+r.h))sum+=.01;}return sum;}
export function rank(rows,weights){const total=Object.values(weights).reduce((a,b)=>a+b,0)||1;return rows.map(r=>({...r,score:(r.heat*weights.heat+r.housing*weights.housing+r.green*weights.green+(r.vulnerability??50)*weights.vulnerability)/total,provisional:r.vulnerability==null||!r.survey})).sort((a,b)=>b.score-a.score);}
export function budget(c){const household=c.area*c.rate+c.prep,available=Math.max(0,c.budget-c.overhead),reached=household>0?Math.min(c.households,Math.floor(available/household)):0;return {household,reached,total:reached*household+c.overhead,remaining:c.budget-reached*household-c.overhead};}
